import { Injectable } from "@nestjs/common";
import type { MessageCollectionDto } from "#/modules/product/schema/dto/message-collection.dto.ts";
import type { MessageWindowDto } from "#/modules/product/schema/dto/message-window.dto.ts";
import { ListMessagesUseCase } from "#/modules/product/features/copy/use-cases/list-messages.repository.ts";

/**
 * The Copy contract the controller calls, then its implementation: each method
 * delegates to the use case for that operation. Regenerated by Dryv; the use cases hold the logic.
 */
export abstract class ProductCopyService {
  abstract listMessages(input: MessageWindowDto): Promise<MessageCollectionDto>;
}

@Injectable()
export class ProductCopyServiceImpl extends ProductCopyService {
  constructor(private readonly listMessagesUseCase: ListMessagesUseCase) {
    super();
  }

  listMessages(input: MessageWindowDto): Promise<MessageCollectionDto> {
    return this.listMessagesUseCase.execute(input);
  }
}
